(179528, 10249, 5892, '<td valign="top">It seems almost surreal! I love the lighting - the entire image is very pleasing to the eye.</td>', 'It seems almost surreal! I love the lighting - the entire image is very pleasing to the eye.', '2002-12-30 03:08:25.000000', NULL, 1),
(179529, 10320, 5892, '<td valign="top">I had to look at it sideways for a second! Really neat picture.</td>', 'I had to look at it sideways for a second! Really neat picture.', '2002-12-30 03:09:24.000000', NULL, 1),
