(179569, 10268, 3942, '<td valign="top">A great concept image with very impressive use of negative space. But unfortunately out of focus. Nevertheless good luck for the challenge!</td>', 'A great concept image with very impressive use of negative space. But unfortunately out of focus. Nevertheless good luck for the challenge!', '2002-12-30 05:52:07.000000', NULL, 1),
(179570, 10337, 2954, '<td valign="top">simply amazing</td>', 'simply amazing', '2002-12-30 05:55:26.000000', NULL, 1),
