(179609, 10290, 3084, '<td valign="top">Wonderful shot, beautiful courtyard.  It reminds me of New Orleans or Key West, sort of a Spanish influence to the architecture.  I wish that the vertical alignment would have been a bit better, otherwise a great effort.  Good luck in the challenge. 8</td>', 'Wonderful shot, beautiful courtyard.  It reminds me of New Orleans or Key West, sort of a Spanish influence to the architecture.  I wish that the vertical alignment would have been a bit better, otherwise a great effort.  Good luck in the challenge. 8', '2002-12-30 08:13:09.000000', NULL, 1),
(179610, 10147, 1003, '<td valign="top">very nicely done</td>', 'very nicely done', '2002-12-30 08:26:00.000000', NULL, 1),
(179611, 10122, 3084, '<td valign="top">Wonderful image, I also take this sort of picture and have rarely achieve equal success, so I know that it can be a challenge.  You must be on the other side of the world from me (Toronto), as Tycos seems to be so different then from the view that I see, when the clouds are all gone.  My pick of the week 10</td>', 'Wonderful image, I also take this sort of picture and have rarely achieve equal success, so I know that it can be a challenge.  You must be on the other side of the world from me (Toronto), as Tycos seems to be so different then from the view that I see, when the clouds are all gone.  My pick of the week 10', '2002-12-30 08:30:07.000000', NULL, 1),
(179630, 10260, 4793, '<td valign="top">Beautiful lighthouse, very nice shot.</td>', 'Beautiful lighthouse, very nice shot.', '2002-12-30 09:54:34.000000', NULL, 1),
(179637, 10195, 92, '<td valign="top">One of my favs ! The tone works great. Thirds used. REALLY nicely done :) = 10 Shiiizzzam</td>', 'One of my favs ! The tone works great. Thirds used. REALLY nicely done :) = 10 Shiiizzzam', '2002-12-30 10:22:39.000000', NULL, 1),
(179638, 10134, 92, '<td valign="top">Beautiful !</td>', 'Beautiful !', '2002-12-30 10:23:23.000000', NULL, 1),
