(179645, 10246, 92, '<td valign="top">One of my favs !  = 10 Shiiizzzam</td>', 'One of my favs !  = 10 Shiiizzzam', '2002-12-30 10:39:23.000000', NULL, 1),
(179647, 10249, 92, '<td valign="top">I love the color tone used. Lighting and interest are right on the money ! Great photo.</td>', 'I love the color tone used. Lighting and interest are right on the money ! Great photo.', '2002-12-30 10:42:33.000000', NULL, 1),
