(180159, 10175, 4380, '<td valign="top">nice black and white photograph.</td>', 'nice black and white photograph.', '2002-12-30 21:26:24.000000', NULL, 1),
(180160, 10256, 1647, '<td valign="top">I commented on this although it seems to have lost it.  Anyway - lovely detail in the bridge and columns.  The sky is great and the water also.  They look like Australian Surf Life Savers.  Correct?</td>', 'I commented on this although it seems to have lost it.  Anyway - lovely detail in the bridge and columns.  The sky is great and the water also.  They look like Australian Surf Life Savers.  Correct?', '2002-12-30 21:26:49.000000', NULL, 1),
