(180168, 10247, 1647, '<td valign="top">Ok, you''ve got me...  I can''t work this out.  Any hints?</td>', 'Ok, you''ve got me...  I can''t work this out.  Any hints?', '2002-12-30 21:34:18.000000', NULL, 1),
(180170, 10195, 1647, '<td valign="top">That''s a great photo.  Definitely worth making a print of.  Great subject!  Good framing and composition as well</td>', 'That''s a great photo.  Definitely worth making a print of.  Great subject!  Good framing and composition as well', '2002-12-30 21:36:35.000000', NULL, 1),
(180171, 10160, 5023, '<td valign="top">Hey...That is really cool...super idea...I would have never thought of that myself.  +9.8</td>', 'Hey...That is really cool...super idea...I would have never thought of that myself.  +9.8', '2002-12-30 21:41:00.000000', NULL, 1),
