(180513, 10145, 3735, '<td valign="top">doesnt look happy lol . Would like to have seen his or her eyes</td>', 'doesnt look happy lol . Would like to have seen his or her eyes', '2002-12-31 14:14:11.000000', NULL, 1),
(180523, 10141, 5918, '<td valign="top">come on now....you can do better than this.</td>', 'come on now....you can do better than this.', '2002-12-31 14:45:32.000000', NULL, 1),
(180536, 10250, 2337, '<td valign="top">This may be art, but it doesn''t work for me...</td>', 'This may be art, but it doesn''t work for me...', '2002-12-31 15:24:34.000000', NULL, 1),
