(181002, 10240, 5822, '<td valign="top">I love these two kids...they are so cute...and the picture reminds me of the fun of being a kid...just not sure what it has to do with travel.</td>', 'I love these two kids...they are so cute...and the picture reminds me of the fun of being a kid...just not sure what it has to do with travel.', '2003-01-02 00:11:18.000000', NULL, 1),
(181012, 10330, 5111, '<td valign="top">Excellent photo! Perhaps a little too much lens glare but overall it is well balanced and the shadows created from the sun are well placed.</td>', 'Excellent photo! Perhaps a little too much lens glare but overall it is well balanced and the shadows created from the sun are well placed.', '2003-01-02 00:15:42.000000', NULL, 1),
