(181180, 10188, 3540, '<td valign="top">Good shot.  I would''ve like to have seen this going a little straighter to give it the "neverending" feel.  I like the choice of B&amp;W for this pic. - Inspzil</td>', 'Good shot.  I would''ve like to have seen this going a little straighter to give it the "neverending" feel.  I like the choice of B&W for this pic. - Inspzil', '2003-01-02 05:19:29.000000', NULL, 1),
(181181, 10172, 3540, '<td valign="top">Have maracas, will travel - Inspzil</td>', 'Have maracas, will travel - Inspzil', '2003-01-02 05:20:38.000000', NULL, 1),
