(181486, 10148, 5896, '<td valign="top">There''s a nice contrast between the airplane and the nets, but the composition isn''t convincing.</td>', 'There''s a nice contrast between the airplane and the nets, but the composition isn''t convincing.', '2003-01-02 18:31:51.000000', NULL, 1),
