(181488, 10202, 4615, '<td valign="top">One of those few times when a wider shot, to show more of the rolling hills, would actually be desirable.  still a good picture.  I think frameless would have worked better.</td>', 'One of those few times when a wider shot, to show more of the rolling hills, would actually be desirable.  still a good picture.  I think frameless would have worked better.', '2003-01-02 18:32:41.000000', NULL, 1),
(181489, 10132, 3735, '<td valign="top">beautiful!!!</td>', 'beautiful!!!', '2003-01-02 18:33:28.000000', NULL, 1),
(181490, 10332, 5896, '<td valign="top">A very nice setting with great colours and light. The picture suffers, though, from the composition with the opening of the shed being crammed into the corner.</td>', 'A very nice setting with great colours and light. The picture suffers, though, from the composition with the opening of the shed being crammed into the corner.', '2003-01-02 18:34:16.000000', NULL, 1),
(181492, 10195, 4615, '<td valign="top">Is this an Icelandic pony?</td>', 'Is this an Icelandic pony?', '2003-01-02 18:34:41.000000', NULL, 1),
(181493, 10128, 1005, '<td valign="top">O.K. religeous bias got me at first, scored this a 3. It is better than that, but this only fits the challenge because your title forces it into that nitche.  Tad of glare from the lower right corner of the circle (either all corners, or none)  Fine photo, but the best I can go is 5.  Swash</td>', 'O.K. religeous bias got me at first, scored this a 3. It is better than that, but this only fits the challenge because your title forces it into that nitche.  Tad of glare from the lower right corner of the circle (either all corners, or none)  Fine photo, but the best I can go is 5.  Swash', '2003-01-02 18:36:13.000000', NULL, 1),
(181494, 10295, 5896, '<td valign="top">Very nice light and a composition with clear movement, giving a measure of poetry to a situation from everyday life.</td>', 'Very nice light and a composition with clear movement, giving a measure of poetry to a situation from everyday life.', '2003-01-02 18:36:15.000000', NULL, 1),
(181496, 10105, 4615, '<td valign="top">That iconoclastic shot.</td>', 'That iconoclastic shot.', '2003-01-02 18:38:06.000000', NULL, 1),
(181497, 10240, 1005, '<td valign="top">Travelling where?  (driving you crazy?)  Cute shot, very nicely taken, but the reference to the challenge is thin at best.  6 Swash</td>', 'Travelling where?  (driving you crazy?)  Cute shot, very nicely taken, but the reference to the challenge is thin at best.  6 Swash', '2003-01-02 18:38:28.000000', NULL, 1),
(181498, 10337, 5896, '<td valign="top">A static picture of a motive seen from postcards from all over the world. The quality is terrible. Is this really a digital photo or is it scanned?</td>', 'A static picture of a motive seen from postcards from all over the world. The quality is terrible. Is this really a digital photo or is it scanned?', '2003-01-02 18:38:34.000000', NULL, 1),
