(181556, 10145, 3705, '<td valign="top">What a crack up!</td>', 'What a crack up!', '2003-01-02 19:43:25.000000', NULL, 1),
(181563, 10100, 2752, '<td valign="top">I like the using of the bathing suit and the passport  tapers back nicely but the (4) items all centered seem too much.  Maybe just one ticket so the items would be (3) would make more of an impact..technically well done.</td>', 'I like the using of the bathing suit and the passport  tapers back nicely but the (4) items all centered seem too much.  Maybe just one ticket so the items would be (3) would make more of an impact..technically well done.', '2003-01-02 20:07:59.000000', NULL, 1),
(181566, 10317, 2752, '<td valign="top">nice use of color..I think an angle shot would have made more of an impact.</td>', 'nice use of color..I think an angle shot would have made more of an impact.', '2003-01-02 20:11:00.000000', NULL, 1),
(181568, 10134, 1202, '<td valign="top">Nice footprints.   Beautiful stting and slow travel.</td>', 'Nice footprints.   Beautiful stting and slow travel.', '2003-01-02 20:14:41.000000', NULL, 1),
(181617, 10237, 3018, '<td valign="top">"too" not "to"</td>', '"too" not "to"', '2003-01-02 22:29:01.000000', NULL, 1),
(181630, 10248, 4813, '<td valign="top">nothing personal but if you are going home I don''t want to live in your neighborhood.  Great Photo.  a little out of focus but still a great photo</td>', 'nothing personal but if you are going home I don''t want to live in your neighborhood.  Great Photo.  a little out of focus but still a great photo', '2003-01-02 22:55:52.000000', NULL, 1),
(181677, 10145, 3936, '<td valign="top">The face is killer!  Looks like someone is definetly tired of travel.  8</td>', 'The face is killer!  Looks like someone is definetly tired of travel.  8', '2003-01-03 01:52:37.000000', NULL, 1),
(181678, 10132, 3936, '<td valign="top">Very nice shot.  Seems a bit static, till you see whatever that is that seems to be going down in flames in the upper right.  Good color, good exposure.  9</td>', 'Very nice shot.  Seems a bit static, till you see whatever that is that seems to be going down in flames in the upper right.  Good color, good exposure.  9', '2003-01-03 01:55:58.000000', NULL, 1),
(181687, 10101, 1686, '<td valign="top">This is truely one of the more imaginative photos, I''d love to know if you knew ahead of time or just came on it and snapped the picture.</td>', 'This is truely one of the more imaginative photos, I''d love to know if you knew ahead of time or just came on it and snapped the picture.', '2003-01-03 02:29:14.000000', NULL, 1),
(181695, 10237, 2279, '<td valign="top">yaaa!!...im going to ha-wai-ii...yaaa!!...im going to ha-wai-ii...yaaa!!...im going to ha-wai-ii!!...yaaa!!</td>', 'yaaa!!...im going to ha-wai-ii...yaaa!!...im going to ha-wai-ii...yaaa!!...im going to ha-wai-ii!!...yaaa!!', '2003-01-03 02:56:14.000000', NULL, 1),
(181712, 10121, 3540, '<td valign="top">The center crop on this would work if not for the tree on the right side throwing the balance off some.  Cool shot nonethess - Inspzil</td>', 'The center crop on this would work if not for the tree on the right side throwing the balance off some.  Cool shot nonethess - Inspzil', '2003-01-03 05:33:21.000000', NULL, 1),
(181724, 10188, 2978, '<td valign="top">Great!!</td>', 'Great!!', '2003-01-03 08:08:15.000000', NULL, 1),
(181728, 10100, 2295, '<td valign="top">Meets the challenge.  Nice color, focus and lighting are good.  7 waltoml.</td>', 'Meets the challenge.  Nice color, focus and lighting are good.  7 waltoml.', '2003-01-03 08:38:45.000000', NULL, 1),
(181729, 10180, 2295, '<td valign="top">I''ll trade you locations...  Nice photo.  Good subject matter.  Lighting and focus look good.  7 waltoml</td>', 'I''ll trade you locations...  Nice photo.  Good subject matter.  Lighting and focus look good.  7 waltoml', '2003-01-03 08:39:59.000000', NULL, 1),
(181731, 10134, 2295, '<td valign="top">Very nice scene.  Lighting and focus look good.  Meets the challenge.  7 waltoml.</td>', 'Very nice scene.  Lighting and focus look good.  Meets the challenge.  7 waltoml.', '2003-01-03 08:41:08.000000', NULL, 1),
(181736, 10317, 3724, '<td valign="top">i like subtle frame a lot....... the trunk appears to be 1940''s us army issue....  a feeling of nostalgia creeps over me looking at this - reminds me of my father''s "loot box."  from the same era, it too is covered with torn stickers and painted military designations  ........the gentle amber atmosphere created by your light is so perfect for this......</td>', 'i like subtle frame a lot....... the trunk appears to be 1940''s us army issue....  a feeling of nostalgia creeps over me looking at this - reminds me of my father''s "loot box."  from the same era, it too is covered with torn stickers and painted military designations  ........the gentle amber atmosphere created by your light is so perfect for this......', '2003-01-03 08:43:14.000000', NULL, 1),
(181740, 10246, 772, '<td valign="top">beautiful shot and excellent exposure to go along with it :)  I can still see all the details in the darker areas and nothing in the window is blown out.  I believe this is my favorite image in this challenge.. great work :) - 10 - setzler</td>', 'beautiful shot and excellent exposure to go along with it :)  I can still see all the details in the darker areas and nothing in the window is blown out.  I believe this is my favorite image in this challenge.. great work :) - 10 - setzler', '2003-01-03 08:59:54.000000', NULL, 1),
(181741, 10131, 5896, '<td valign="top">Uninteresting, poor composition (why are peoples heads left out so often?), static...</td>', 'Uninteresting, poor composition (why are peoples heads left out so often?), static...', '2003-01-03 09:01:59.000000', NULL, 1),
(181742, 10220, 5896, '<td valign="top">It''s interesting to capture where one''s coming from and the picture has nice movement. The image as such should be sharper though and the motive in the rear mirror doesn''t really inspire (it''s just a piece of road...).</td>', 'It''s interesting to capture where one''s coming from and the picture has nice movement. The image as such should be sharper though and the motive in the rear mirror doesn''t really inspire (it''s just a piece of road...).', '2003-01-03 09:05:03.000000', NULL, 1),
(181743, 10147, 5896, '<td valign="top">A nice picture and a motive hard to capture since the windows of the airplane often distort any attempt to take good pictures. It is a bit static though.</td>', 'A nice picture and a motive hard to capture since the windows of the airplane often distort any attempt to take good pictures. It is a bit static though.', '2003-01-03 09:08:01.000000', NULL, 1),
(181746, 10177, 5896, '<td valign="top">A nice commentary to the theme. The image is a bit dark in the wrong places though and the image quality could have been better.</td>', 'A nice commentary to the theme. The image is a bit dark in the wrong places though and the image quality could have been better.', '2003-01-03 09:10:01.000000', NULL, 1),
(181747, 10337, 3102, '<td valign="top">On one hand, it''s a very pretty scene, but there are a couple things that bother me here.  One, it seems tilted too far to the right (the water looks like it could spill off the side of the frame), and there''s something disturbing about the quality of the image -- it almost looks as though it was scanned on a poor scanner rather than as a digital camera image.  At 72K, it''s only 1/2 the compression quality allowed on the site.</td>', 'On one hand, it''s a very pretty scene, but there are a couple things that bother me here.  One, it seems tilted too far to the right (the water looks like it could spill off the side of the frame), and there''s something disturbing about the quality of the image -- it almost looks as though it was scanned on a poor scanner rather than as a digital camera image.  At 72K, it''s only 1/2 the compression quality allowed on the site.', '2003-01-03 09:20:18.000000', NULL, 1),
(181749, 10101, 3102, '<td valign="top">Too bad it''s overwhelmingly grainy... it''s a good idea!</td>', 'Too bad it''s overwhelmingly grainy... it''s a good idea!', '2003-01-03 09:21:11.000000', NULL, 1),
(181760, 10167, 3724, '<td valign="top">i give ten in support of our troops.......  nine for this photograph.......  and zero points to George Bush''s reckless American Imperialism.....</td>', 'i give ten in support of our troops.......  nine for this photograph.......  and zero points to George Bush''s reckless American Imperialism.....', '2003-01-03 09:56:07.000000', NULL, 1),
(181762, 10260, 1185, '<td valign="top">The lighting here is incredible! I\''d love to know how you got the grass so well lit up front and the light sky to pop so well in the background. Great work!</td>', 'The lighting here is incredible! I\''d love to know how you got the grass so well lit up front and the light sky to pop so well in the background. Great work!', '2003-01-03 09:56:57.000000', NULL, 1),
(181850, 10337, 4159, '<td valign="top">This really has the feel of a watercolor - nice color balance.</td>', 'This really has the feel of a watercolor - nice color balance.', '2003-01-03 12:47:21.000000', NULL, 1),
(181851, 10168, 4159, '<td valign="top">Power lines and power towers are not usually aesthetically pleasing; also, your scaling has given them the appearance of dotted lines.</td>', 'Power lines and power towers are not usually aesthetically pleasing; also, your scaling has given them the appearance of dotted lines.', '2003-01-03 12:48:08.000000', NULL, 1),
(181852, 10299, 4159, '<td valign="top">The sky is nice, but it doesn''t have much oomph to it; you might consider cropping out the sides and keeping the towers in the center; skinny, but it''d be effective.</td>', 'The sky is nice, but it doesn''t have much oomph to it; you might consider cropping out the sides and keeping the towers in the center; skinny, but it''d be effective.', '2003-01-03 12:49:42.000000', NULL, 1),
(181853, 10336, 4159, '<td valign="top">Pretty neat, if that''s a plane going by.  A few too many glaring lights, though.</td>', 'Pretty neat, if that''s a plane going by.  A few too many glaring lights, though.', '2003-01-03 12:50:48.000000', NULL, 1),
(181854, 10229, 4159, '<td valign="top">Something besides the chair needs to be in focus here.</td>', 'Something besides the chair needs to be in focus here.', '2003-01-03 12:51:17.000000', NULL, 1),
(181855, 10294, 4159, '<td valign="top">The angle here isn''t very exciting, and without something to distinguish this, it''s another old train picture.  Photographically, you divide it in thirds and the focus is good, but the subject is lacking.</td>', 'The angle here isn''t very exciting, and without something to distinguish this, it''s another old train picture.  Photographically, you divide it in thirds and the focus is good, but the subject is lacking.', '2003-01-03 12:53:21.000000', NULL, 1),
(181856, 10283, 4159, '<td valign="top">Focus is a bit of a problem here.</td>', 'Focus is a bit of a problem here.', '2003-01-03 12:53:45.000000', NULL, 1),
(181857, 10316, 4159, '<td valign="top">Focus, angle, and interest level are problems here.</td>', 'Focus, angle, and interest level are problems here.', '2003-01-03 12:54:37.000000', NULL, 1),
(181859, 10158, 4159, '<td valign="top">Interesting angle, I like how the tracks cross together in the front.  I would''ve tried to crop out or find an angle which didn''t include the mess at the top, though.</td>', 'Interesting angle, I like how the tracks cross together in the front.  I would''ve tried to crop out or find an angle which didn''t include the mess at the top, though.', '2003-01-03 12:55:39.000000', NULL, 1),
(181860, 10290, 4159, '<td valign="top">Something weird about this, might''ve happened in the scaling or a focus fix.  Everything''s dotty and lines are indistinct.</td>', 'Something weird about this, might''ve happened in the scaling or a focus fix.  Everything''s dotty and lines are indistinct.', '2003-01-03 12:56:32.000000', NULL, 1),
(181861, 10147, 4159, '<td valign="top">Pretty good for a plane window - you''re lucky, I always get the wing.</td>', 'Pretty good for a plane window - you''re lucky, I always get the wing.', '2003-01-03 12:57:05.000000', NULL, 1),
(181864, 10236, 4159, '<td valign="top">The hairs are a bit odd.</td>', 'The hairs are a bit odd.', '2003-01-03 12:58:22.000000', NULL, 1),
(181866, 10089, 4159, '<td valign="top">Looks like a car commercial.  nice use of negative space.</td>', 'Looks like a car commercial.  nice use of negative space.', '2003-01-03 12:58:47.000000', NULL, 1),
(181867, 10325, 4159, '<td valign="top">Ah, that''ll stuff in.  Sit on it.</td>', 'Ah, that''ll stuff in.  Sit on it.', '2003-01-03 12:59:02.000000', NULL, 1),
(181868, 10135, 4159, '<td valign="top">Lighting on the subjects is pretty feeble, can''t see his face at all.</td>', 'Lighting on the subjects is pretty feeble, can''t see his face at all.', '2003-01-03 13:00:06.000000', NULL, 1),
(181870, 10289, 4159, '<td valign="top">It''s both - nice picture.  Would''ve been neat if the bird had been at the end of the plane''s path, but I guess you couldn''t do anything about that.</td>', 'It''s both - nice picture.  Would''ve been neat if the bird had been at the end of the plane''s path, but I guess you couldn''t do anything about that.', '2003-01-03 13:01:13.000000', NULL, 1),
(181871, 10253, 4159, '<td valign="top">A little too bright for my taste, edges of the mountains are fuzzy.  Nice capture of the couple, though.</td>', 'A little too bright for my taste, edges of the mountains are fuzzy.  Nice capture of the couple, though.', '2003-01-03 13:02:29.000000', NULL, 1),
(181872, 10200, 4159, '<td valign="top">A bit hard to read.  Also, focus and framing is weird.  Nothing seems to be the subject of the picture, at least photographically.</td>', 'A bit hard to read.  Also, focus and framing is weird.  Nothing seems to be the subject of the picture, at least photographically.', '2003-01-03 13:03:41.000000', NULL, 1),
(181873, 10237, 4159, '<td valign="top">Funny.</td>', 'Funny.', '2003-01-03 13:04:43.000000', NULL, 1),
(181874, 10210, 4159, '<td valign="top">The reflections on the water are really nice, but the rest of the lights are too glaring - shorter shutter speed might''ve worked better.  Also, the sign at the left is distracting.</td>', 'The reflections on the water are really nice, but the rest of the lights are too glaring - shorter shutter speed might''ve worked better.  Also, the sign at the left is distracting.', '2003-01-03 13:05:38.000000', NULL, 1),
(181875, 10094, 4159, '<td valign="top">Does look like a Christmas tree - this picture is strangely aesthetically pleasing.  Nice use of negative space.</td>', 'Does look like a Christmas tree - this picture is strangely aesthetically pleasing.  Nice use of negative space.', '2003-01-03 13:06:16.000000', NULL, 1),
(181877, 10248, 4159, '<td valign="top">Would''ve liked either the gravestones to be more in focus or the hearse to take up more of the picture.  Interesting concept of travel.</td>', 'Would''ve liked either the gravestones to be more in focus or the hearse to take up more of the picture.  Interesting concept of travel.', '2003-01-03 13:07:34.000000', NULL, 1),
(181878, 10302, 4159, '<td valign="top">You haven''t done anything very memorable with the Alamo.</td>', 'You haven''t done anything very memorable with the Alamo.', '2003-01-03 13:08:01.000000', NULL, 1),
(181879, 10328, 4159, '<td valign="top">Actually looks like they''re running, nice effect.</td>', 'Actually looks like they''re running, nice effect.', '2003-01-03 13:08:21.000000', NULL, 1),
(181880, 10230, 4159, '<td valign="top">Shutter speed''s just a bit too long, should''ve tried not to catch the street light on the bottom left.</td>', 'Shutter speed''s just a bit too long, should''ve tried not to catch the street light on the bottom left.', '2003-01-03 13:08:57.000000', NULL, 1),
(181882, 10240, 4159, '<td valign="top">Looks a little too posed, and the colors look washed out..  More contrast or a different choice in backround would''ve worked better.</td>', 'Looks a little too posed, and the colors look washed out..  More contrast or a different choice in backround would''ve worked better.', '2003-01-03 13:10:04.000000', NULL, 1),
(181883, 10170, 4159, '<td valign="top">Very nice picture, kind of seems like you stretched a bit to make it fit the challenge, but the picture itself is well done.</td>', 'Very nice picture, kind of seems like you stretched a bit to make it fit the challenge, but the picture itself is well done.', '2003-01-03 13:10:46.000000', NULL, 1),
