(182208, 10160, 5896, '<td valign="top">A lovely picture inviting the viewer to be the first to explore where the path is going. The sparse colouring of winter adds to the quality of the image.</td>', 'A lovely picture inviting the viewer to be the first to explore where the path is going. The sparse colouring of winter adds to the quality of the image.', '2003-01-04 09:35:41.000000', NULL, 1),
(182209, 10257, 5896, '<td valign="top">The crowded marina gives a promise of activity and adventures at sea. The picture is a bit too bright though and the motive isn''t that original.</td>', 'The crowded marina gives a promise of activity and adventures at sea. The picture is a bit too bright though and the motive isn''t that original.', '2003-01-04 09:39:59.000000', NULL, 1),
(182210, 10337, 326, '<td valign="top">Looks like a post card! Great job!</td>', 'Looks like a post card! Great job!', '2003-01-04 09:45:49.000000', NULL, 1),
(182212, 10199, 326, '<td valign="top">Cute photo...good job.</td>', 'Cute photo...good job.', '2003-01-04 09:52:42.000000', NULL, 1),
(182217, 10246, 1280, '<td valign="top">Cute and well done! This is my favorite for the week.  9</td>', 'Cute and well done! This is my favorite for the week.  9', '2003-01-04 10:26:32.000000', NULL, 1),
(182219, 10101, 1280, '<td valign="top">Very nice, interesting image.  How''d ya do it? 8</td>', 'Very nice, interesting image.  How''d ya do it? 8', '2003-01-04 10:27:33.000000', NULL, 1),
(182236, 10116, 2856, '<td valign="top">lighting could have been  better.</td>', 'lighting could have been  better.', '2003-01-04 11:24:19.000000', NULL, 1),
(182237, 10176, 2856, '<td valign="top">I think a non-centred compostion would have been better.</td>', 'I think a non-centred compostion would have been better.', '2003-01-04 11:26:16.000000', NULL, 1),
(182241, 10260, 5351, '<td valign="top">Really like the contrast!</td>', 'Really like the contrast!', '2003-01-04 11:47:53.000000', NULL, 1),
(182242, 10291, 5351, '<td valign="top">Really like this photo!  Love the composition, colors, and focus.  Great shot.</td>', 'Really like this photo!  Love the composition, colors, and focus.  Great shot.', '2003-01-04 11:55:31.000000', NULL, 1),
(182246, 10246, 5896, '<td valign="top">It''s a lovely picture capturing an intimate momemt between the child and his or her journey in space and time alike. Frome here to there but also from childhood into the future. The subdued light in the train contrasts well with the bright exterior and the stillness inside with the movement outside.</td>', 'It''s a lovely picture capturing an intimate momemt between the child and his or her journey in space and time alike. Frome here to there but also from childhood into the future. The subdued light in the train contrasts well with the bright exterior and the stillness inside with the movement outside.', '2003-01-04 12:22:52.000000', NULL, 1),
(182247, 10255, 5896, '<td valign="top">A nice commentary to the theme although the picture as such is fairly plain.</td>', 'A nice commentary to the theme although the picture as such is fairly plain.', '2003-01-04 12:24:58.000000', NULL, 1),
(182249, 10301, 5896, '<td valign="top">Is she travelling on ''Rosebud'' into or away from suburbia? Apart from being a comment to the theme the picture as such doesn''t really have any extra qualities.</td>', 'Is she travelling on ''Rosebud'' into or away from suburbia? Apart from being a comment to the theme the picture as such doesn''t really have any extra qualities.', '2003-01-04 12:29:40.000000', NULL, 1),
(182250, 10276, 5896, '<td valign="top">A good comment to the theme and an image of the beauty of nature.</td>', 'A good comment to the theme and an image of the beauty of nature.', '2003-01-04 12:31:14.000000', NULL, 1),
(182252, 10249, 5896, '<td valign="top">A nice crisp image fully utilizing the contrasts possible in b/w. It''s also a nice comment on the theme with the empty seats waiting to be filled with purpose and direction.</td>', 'A nice crisp image fully utilizing the contrasts possible in b/w. It''s also a nice comment on the theme with the empty seats waiting to be filled with purpose and direction.', '2003-01-04 12:33:46.000000', NULL, 1),
(182254, 10258, 5896, '<td valign="top">Poor connection to the theme, unbalanced perspective lines (deadly sin taking pictures of architecture) and the colouring being a bit bland with the grey buildings vs. an equally grey sky.</td>', 'Poor connection to the theme, unbalanced perspective lines (deadly sin taking pictures of architecture) and the colouring being a bit bland with the grey buildings vs. an equally grey sky.', '2003-01-04 12:39:05.000000', NULL, 1),
(182269, 10266, 5369, '<td valign="top">Photography fair--not much interest</td>', 'Photography fair--not much interest', '2003-01-04 13:56:45.000000', NULL, 1),
(182284, 10195, 4411, '<td valign="top">Lovely composition, the sepia works well here. Love the 80''s ''New Romantic'' fringe ;)</td>', 'Lovely composition, the sepia works well here. Love the 80''s ''New Romantic'' fringe ;)', '2003-01-04 15:58:41.000000', NULL, 1),
(182286, 10295, 4411, '<td valign="top">Great shot. Fog always seems to work well and this is no exception. Well done.</td>', 'Great shot. Fog always seems to work well and this is no exception. Well done.', '2003-01-04 16:00:51.000000', NULL, 1),
(182288, 10266, 4411, '<td valign="top">Great shot, not so great driving conditions. I really like the composition, you caught the Jeep at just the right spot. Well done.</td>', 'Great shot, not so great driving conditions. I really like the composition, you caught the Jeep at just the right spot. Well done.', '2003-01-04 16:04:05.000000', NULL, 1),
(182325, 10122, 5508, '<td valign="top">This photo could''nt have been taken the last weekof Dec. Not that I care. I like the shot very much. I would like to know the equipment used. However what does the moon have to do with travelling?</td>', 'This photo could''nt have been taken the last weekof Dec. Not that I care. I like the shot very much. I would like to know the equipment used. However what does the moon have to do with travelling?', '2003-01-04 16:55:03.000000', NULL, 1),
(182326, 10101, 5508, '<td valign="top">This shot could''nt have been taken on the last week in DEC.</td>', 'This shot could''nt have been taken on the last week in DEC.', '2003-01-04 16:59:32.000000', NULL, 1),
(182330, 10147, 5313, '<td valign="top">That''s a lovely scene--and the windows of the plane weren''t even dirty!!!  ;o)<br/> <br/>Where is it 33,000 feet above?</td>', 'That''s a lovely scene--and the windows of the plane weren''t even dirty!!!  ;o) Where is it 33,000 feet above?', '2003-01-04 17:50:42.000000', NULL, 1),
(182333, 10301, 5313, '<td valign="top">What fun!</td>', 'What fun!', '2003-01-04 17:55:58.000000', NULL, 1),
(182353, 10256, 3032, '<td valign="top">Interesting composition. Clear shot. Like the choice of aperture.</td>', 'Interesting composition. Clear shot. Like the choice of aperture.', '2003-01-04 19:07:24.000000', NULL, 1),
(182354, 10170, 3032, '<td valign="top">Original subject. :)<br/>Good field of focus on the main subject. Sharp, nice colors.<br/>Wonder what a tighter crop will do.</td>', 'Original subject. :)Good field of focus on the main subject. Sharp, nice colors.Wonder what a tighter crop will do.', '2003-01-04 19:09:03.000000', NULL, 1),
(182356, 10236, 1379, '<td valign="top">I love your sense of humor!  Their little ears are so precious and funny!</td>', 'I love your sense of humor!  Their little ears are so precious and funny!', '2003-01-04 19:10:13.000000', NULL, 1),
(182357, 10264, 1379, '<td valign="top">Wow... your passports look so NEW and unrumpled!</td>', 'Wow... your passports look so NEW and unrumpled!', '2003-01-04 19:11:18.000000', NULL, 1),
(182358, 10195, 3032, '<td valign="top">Like the depth of focus and composition. Interesting color, but it seems a bit too much red/pink. Wonder what another duotone (perharps it is more than that, can''t see that) would do.</td>', 'Like the depth of focus and composition. Interesting color, but it seems a bit too much red/pink. Wonder what another duotone (perharps it is more than that, can''t see that) would do.', '2003-01-04 19:11:29.000000', NULL, 1),
(182360, 10327, 1379, '<td valign="top">Gotta love those tight corduroy trousers for hiking!</td>', 'Gotta love those tight corduroy trousers for hiking!', '2003-01-04 19:12:08.000000', NULL, 1),
(182361, 10332, 1379, '<td valign="top">Beautiful composition.  I especially like the way the fence and the horizon divide the photo into horizontal sections.  The sky looks incredible.</td>', 'Beautiful composition.  I especially like the way the fence and the horizon divide the photo into horizontal sections.  The sky looks incredible.', '2003-01-04 19:12:55.000000', NULL, 1),
(182362, 10276, 3032, '<td valign="top">Very clear shot, the birds seem to be very far away. Yet there is still detail under the wings and in the head area. Shot with a low sun? The frame enhances the image, not bad at all.</td>', 'Very clear shot, the birds seem to be very far away. Yet there is still detail under the wings and in the head area. Shot with a low sun? The frame enhances the image, not bad at all.', '2003-01-04 19:13:18.000000', NULL, 1),
(182364, 10089, 1379, '<td valign="top">This could be an ad for your car!  The red is such a nice contrast against the cold world there.</td>', 'This could be an ad for your car!  The red is such a nice contrast against the cold world there.', '2003-01-04 19:13:33.000000', NULL, 1),
(182368, 10217, 3032, '<td valign="top">Funny subject. Nice composition, good color. <br/>Seems to be overexposed at the right and in the background. Perhaps that could be avoided? Too bad a tighter crop would go throug the sign.</td>', 'Funny subject. Nice composition, good color. Seems to be overexposed at the right and in the background. Perhaps that could be avoided? Too bad a tighter crop would go throug the sign.', '2003-01-04 19:16:07.000000', NULL, 1),
(182371, 10121, 1379, '<td valign="top">Did you take a handful of dirt?  :-)</td>', 'Did you take a handful of dirt?  :-)', '2003-01-04 19:17:11.000000', NULL, 1),
(182375, 10253, 3032, '<td valign="top">Oh yeah, mountain roads rule! I bet the person is pointing excitedly at some twisties and hairpins. :)</td>', 'Oh yeah, mountain roads rule! I bet the person is pointing excitedly at some twisties and hairpins. :)', '2003-01-04 19:20:35.000000', NULL, 1),
(182376, 10159, 4615, '<td valign="top">I like the darkness.  There seems to be a lack of integration between the parts.</td>', 'I like the darkness.  There seems to be a lack of integration between the parts.', '2003-01-04 19:21:36.000000', NULL, 1),
(182377, 10134, 5826, '<td valign="top">Love the photo.  Just wish the car wasn''t in the shot, and the footprints in the snow.  Still a great shot.</td>', 'Love the photo.  Just wish the car wasn''t in the shot, and the footprints in the snow.  Still a great shot.', '2003-01-04 19:22:31.000000', NULL, 1),
(182379, 10167, 4615, '<td valign="top">contrast seems to be turned up to high.  Are you making a morbid statement about the impending war with the black clothing?</td>', 'contrast seems to be turned up to high.  Are you making a morbid statement about the impending war with the black clothing?', '2003-01-04 19:27:24.000000', NULL, 1),
(182381, 10237, 4615, '<td valign="top">Can''t argue with that.  Would have given you credit for a cynical, biting commentary of DPC, if you had spelled "too" correctly.</td>', 'Can''t argue with that.  Would have given you credit for a cynical, biting commentary of DPC, if you had spelled "too" correctly.', '2003-01-04 19:29:26.000000', NULL, 1),
(182383, 10317, 4411, '<td valign="top">Personally I would have cropped just into the case to completely get rid of the background/carpet, but that''s probably just me.<br/>Nice old, battered looking case and a good idea for the challenge. Lacks a focal point but I do seem to like brown shots.</td>', 'Personally I would have cropped just into the case to completely get rid of the background/carpet, but that''s probably just me.Nice old, battered looking case and a good idea for the challenge. Lacks a focal point but I do seem to like brown shots.', '2003-01-04 19:30:15.000000', NULL, 1),
(182384, 10188, 5826, '<td valign="top">Wow.  I love this shot.  10 all the way.  You will win.</td>', 'Wow.  I love this shot.  10 all the way.  You will win.', '2003-01-04 19:31:28.000000', NULL, 1),
(182386, 10190, 4615, '<td valign="top">I like the sparsness of this picture, could be seen as an abstract interpretation of contrastion lines.  bumped up from 1 to 6 on second pass.</td>', 'I like the sparsness of this picture, could be seen as an abstract interpretation of contrastion lines.  bumped up from 1 to 6 on second pass.', '2003-01-04 19:32:57.000000', NULL, 1),
(182388, 10312, 1031, '<td valign="top">I have a photo from my last vacation with the same theme...</td>', 'I have a photo from my last vacation with the same theme...', '2003-01-04 19:33:06.000000', NULL, 1),
(182391, 10277, 4615, '<td valign="top">very clear and crisp.  a solid 7</td>', 'very clear and crisp.  a solid 7', '2003-01-04 19:34:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(182395, 10087, 4411, '<td valign="top">Would have liked to have seen some more space around the car: it''s cropped too close at the back and I can''t understand why you''ve used a narrow shape instead of the usual 4:3 ratio, I''m sure the trees can''t have been that distracting.<br/>Having said that the photo is quite good. The car is nice &amp; sharp and I like the low angle you''ve shot from. The B&amp;W also helps as I can only imagine how bad the car looks in colour.</td>', 'Would have liked to have seen some more space around the car: it''s cropped too close at the back and I can''t understand why you''ve used a narrow shape instead of the usual 4:3 ratio, I''m sure the trees can''t have been that distracting.Having said that the photo is quite good. The car is nice & sharp and I like the low angle you''ve shot from. The B&W also helps as I can only imagine how bad the car looks in colour.', '2003-01-04 19:40:47.000000', NULL, 1),
(182397, 10140, 4615, '<td valign="top">I''m actually IN this picture!!!!   My apartment is in the smaller building between the second and third of the three towers (they are Columbia student housing)  far right side.</td>', 'I''m actually IN this picture!!!!   My apartment is in the smaller building between the second and third of the three towers (they are Columbia student housing)  far right side.', '2003-01-04 19:42:27.000000', NULL, 1),
(182401, 10235, 4615, '<td valign="top">If this relates to the challenge, it must be in an abstract way, (twisted roads?)  which is a good thing.  Technically, it is superb. a 9</td>', 'If this relates to the challenge, it must be in an abstract way, (twisted roads?)  which is a good thing.  Technically, it is superb. a 9', '2003-01-04 19:46:12.000000', NULL, 1),
(182403, 10260, 4411, '<td valign="top">Good dramatic shadows &amp; clouds. A very striking picture. Well done.</td>', 'Good dramatic shadows & clouds. A very striking picture. Well done.', '2003-01-04 19:49:17.000000', NULL, 1),
(182405, 10095, 1031, '<td valign="top">Excellent use of angles/perspective</td>', 'Excellent use of angles/perspective', '2003-01-04 19:52:41.000000', NULL, 1),
(182406, 10100, 4615, '<td valign="top">very, very crisp.  on the negative side, i find the crop a tad narrow.  Is that a bathing suit under the passport/  If so, would have been good to see more of it.  Dealer''s choice.</td>', 'very, very crisp.  on the negative side, i find the crop a tad narrow.  Is that a bathing suit under the passport/  If so, would have been good to see more of it.  Dealer''s choice.', '2003-01-04 19:54:12.000000', NULL, 1),
(182407, 10188, 1031, '<td valign="top">Cowcatcher''s View</td>', 'Cowcatcher''s View', '2003-01-04 19:54:44.000000', NULL, 1),
(182409, 10084, 4615, '<td valign="top">quite dramatic.  Could have used less of the water, and more of the buildings.</td>', 'quite dramatic.  Could have used less of the water, and more of the buildings.', '2003-01-04 19:56:06.000000', NULL, 1),
(182410, 10101, 1031, '<td valign="top">Pretty grainy but a very cool idea.</td>', 'Pretty grainy but a very cool idea.', '2003-01-04 19:56:57.000000', NULL, 1),
(182411, 10163, 4411, '<td valign="top">Great composition. Not sure about the colour and I don''t like the huge blown out area (and the smaller area on the prop casing) but I do like the idea.</td>', 'Great composition. Not sure about the colour and I don''t like the huge blown out area (and the smaller area on the prop casing) but I do like the idea.', '2003-01-04 19:59:08.000000', NULL, 1),
(182412, 10188, 4615, '<td valign="top">a little bottom heavy, but really conveys travel.  bumped up from 5 to 7 on second pass.</td>', 'a little bottom heavy, but really conveys travel.  bumped up from 5 to 7 on second pass.', '2003-01-04 20:00:48.000000', NULL, 1),
(182413, 10235, 1031, '<td valign="top">No thanks...I''ll be happy to donate my ticket to a more worthy afficionado...</td>', 'No thanks...I''ll be happy to donate my ticket to a more worthy afficionado...', '2003-01-04 20:00:53.000000', NULL, 1),
(182414, 10251, 1031, '<td valign="top">You certainly benefitted from a favorable seat and lighting angle -- glad you were able to take advantage.</td>', 'You certainly benefitted from a favorable seat and lighting angle -- glad you were able to take advantage.', '2003-01-04 20:04:59.000000', NULL, 1),
(182415, 10302, 1031, '<td valign="top">Maybe it''s the dark sky or the fenceposts, but this is the first time I''ve seen how SMALL the place is.</td>', 'Maybe it''s the dark sky or the fenceposts, but this is the first time I''ve seen how SMALL the place is.', '2003-01-04 20:06:56.000000', NULL, 1),
(182416, 10255, 1031, '<td valign="top">Is that a graph of projected velocity or ticket prices?</td>', 'Is that a graph of projected velocity or ticket prices?', '2003-01-04 20:09:01.000000', NULL, 1),
(182417, 10169, 1031, '<td valign="top">Hope it''s not with some wacko who can''t spell...</td>', 'Hope it''s not with some wacko who can''t spell...', '2003-01-04 20:12:49.000000', NULL, 1),
(182433, 10089, 2716, '<td valign="top">I like this composition.  Was unexpected when I was scroling down.  Dodge Durango?  Sweet.  Good job.  Jacko  9.  The only change ... the photo looks a little tilted to the left.  Maybe the tree was just crooked.  Good luck.</td>', 'I like this composition.  Was unexpected when I was scroling down.  Dodge Durango?  Sweet.  Good job.  Jacko  9.  The only change ... the photo looks a little tilted to the left.  Maybe the tree was just crooked.  Good luck.', '2003-01-04 20:33:28.000000', NULL, 1),
