(182436, 10295, 2716, '<td valign="top">I like this.  Is this what is called high key?  I dunno, but I like it.  Great shot.  Jacko 9</td>', 'I like this.  Is this what is called high key?  I dunno, but I like it.  Great shot.  Jacko 9', '2003-01-04 20:34:22.000000', NULL, 1),
(182437, 10237, 2716, '<td valign="top">Good job.  Too bad most people will give you 2 or 3s.  I''ll give you a 4.  Jacko.  Better luck next time.</td>', 'Good job.  Too bad most people will give you 2 or 3s.  I''ll give you a 4.  Jacko.  Better luck next time.', '2003-01-04 20:35:13.000000', NULL, 1),
(182438, 10256, 2716, '<td valign="top">I find the bridge very distracting (lol just kidding; I''m sure some people told you that though).  Excellent framing and very crisp colours.  I love it.  a well deserved 10.  Jacko.</td>', 'I find the bridge very distracting (lol just kidding; I''m sure some people told you that though).  Excellent framing and very crisp colours.  I love it.  a well deserved 10.  Jacko.', '2003-01-04 20:36:19.000000', NULL, 1),
(182439, 10170, 2716, '<td valign="top">Super macro shot.  Great colours.  I like it.  Jacko  9</td>', 'Super macro shot.  Great colours.  I like it.  Jacko  9', '2003-01-04 20:36:40.000000', NULL, 1),
(182440, 10160, 2716, '<td valign="top">Yessir good eye.  I''m going out there tomrorrow in the snow.  Hopefully I''ll come back with a couple of gems like this one.  Excellent work.  9</td>', 'Yessir good eye.  I''m going out there tomrorrow in the snow.  Hopefully I''ll come back with a couple of gems like this one.  Excellent work.  9', '2003-01-04 20:37:19.000000', NULL, 1),
