(182444, 10246, 2716, '<td valign="top">Cute shot. I like the motion blur  Jacko</td>', 'Cute shot. I like the motion blur  Jacko', '2003-01-04 20:40:03.000000', NULL, 1),
(182445, 10092, 2716, '<td valign="top">Nice lighting job.</td>', 'Nice lighting job.', '2003-01-04 20:40:19.000000', NULL, 1),
(182447, 10249, 2716, '<td valign="top">Good eye.  I love these kind of shots.  I love the symetry and the use of B&amp;W.  Good work.  Jacko  9</td>', 'Good eye.  I love these kind of shots.  I love the symetry and the use of B&W.  Good work.  Jacko  9', '2003-01-04 20:41:22.000000', NULL, 1),
(182449, 10158, 2716, '<td valign="top">I found it too buzy at first but I find it very interesting now.   I like the curves and the lines.  Nice capture.  Jacko.</td>', 'I found it too buzy at first but I find it very interesting now.   I like the curves and the lines.  Nice capture.  Jacko.', '2003-01-04 20:42:07.000000', NULL, 1),
