(182665, 10215, 2716, '<td valign="top">Nice pan shot.   I really like the motion blur.  Somehow though, it doesn''t say "I''m so late"; kinda look like a casual strole.  That''s just me.  Good luck.  Jacko.  8</td>', 'Nice pan shot.   I really like the motion blur.  Somehow though, it doesn''t say "I''m so late"; kinda look like a casual strole.  That''s just me.  Good luck.  Jacko.  8', '2003-01-05 07:54:21.000000', NULL, 1),
(182666, 10202, 2716, '<td valign="top">Nice cuves!  I love the composition you used:  really gives the impression that he''s going somewhere.  Jacko.</td>', 'Nice cuves!  I love the composition you used:  really gives the impression that he''s going somewhere.  Jacko.', '2003-01-05 07:55:17.000000', NULL, 1),
(182667, 10165, 2716, '<td valign="top">I like these shots, but I think they''ve been overdone since the motio challenge.  Jacko.</td>', 'I like these shots, but I think they''ve been overdone since the motio challenge.  Jacko.', '2003-01-05 07:55:56.000000', NULL, 1),
(182669, 10280, 2716, '<td valign="top">Wish I was there dude.  I''m in (BRRRR) Canada.  Nice colours.  I like the curve of the beach.  Jacko.</td>', 'Wish I was there dude.  I''m in (BRRRR) Canada.  Nice colours.  I like the curve of the beach.  Jacko.', '2003-01-05 07:56:57.000000', NULL, 1),
(182670, 10175, 2716, '<td valign="top">Great view, with not in full colour?  Good luck.  Jacko.</td>', 'Great view, with not in full colour?  Good luck.  Jacko.', '2003-01-05 07:57:26.000000', NULL, 1),
(182671, 10228, 2716, '<td valign="top">Here''s that cute again ... same  model as the other challenge.  But guess what, I''ll give you a 9 because she so cute and the picture really depicts Australia to me.  Good job.  Jacko.</td>', 'Here''s that cute again ... same  model as the other challenge.  But guess what, I''ll give you a 9 because she so cute and the picture really depicts Australia to me.  Good job.  Jacko.', '2003-01-05 07:59:07.000000', NULL, 1),
(182673, 10266, 2716, '<td valign="top">Yessir, I know the feeling.  Fellow Canadian? (oops I guess not, I just saw the license plate).  Nice composition.    Jakco.</td>', 'Yessir, I know the feeling.  Fellow Canadian? (oops I guess not, I just saw the license plate).  Nice composition.    Jakco.', '2003-01-05 08:02:09.000000', NULL, 1),
(182674, 10294, 2716, '<td valign="top">Nice colours, however seems like it should be tilted to the left sightly and the letters are distractring.  Good luck.  Jacko.</td>', 'Nice colours, however seems like it should be tilted to the left sightly and the letters are distractring.  Good luck.  Jacko.', '2003-01-05 08:03:47.000000', NULL, 1),
(182675, 10271, 2716, '<td valign="top">Nice mix of motion and static subjects.  Jackol.</td>', 'Nice mix of motion and static subjects.  Jackol.', '2003-01-05 08:04:13.000000', NULL, 1),
(182676, 10122, 2716, '<td valign="top">Now that''s a great shot of the moon, probably the best one on DPC yet.  good job.  Jakco.  9</td>', 'Now that''s a great shot of the moon, probably the best one on DPC yet.  good job.  Jakco.  9', '2003-01-05 08:05:22.000000', NULL, 1),
