(182700, 10295, 326, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2003-01-05 10:35:21.000000', NULL, 1),
(182723, 10222, 1031, '<td valign="top">Surprisingly good detail on the plane considering how long a shot this is -- well-done!</td>', 'Surprisingly good detail on the plane considering how long a shot this is -- well-done!', '2003-01-05 12:40:16.000000', NULL, 1),
(182727, 10266, 3889, '<td valign="top">What a wonderful picture.</td>', 'What a wonderful picture.', '2003-01-05 12:51:18.000000', NULL, 1),
(182728, 10237, 1031, '<td valign="top">Wish it had been a bit brighter (the lighting, not the wit), but it would have been hard to keep the lines on the paper.<br/>I wonder how many people take the sentence''s meaning as written, or as they would if they assume a mis-spelling in the first line...?</td>', 'Wish it had been a bit brighter (the lighting, not the wit), but it would have been hard to keep the lines on the paper.I wonder how many people take the sentence''s meaning as written, or as they would if they assume a mis-spelling in the first line...?', '2003-01-05 12:51:46.000000', NULL, 1),
(182729, 10247, 3889, '<td valign="top">This picture seems a little grainy to me.  Great shot of the arch though.</td>', 'This picture seems a little grainy to me.  Great shot of the arch though.', '2003-01-05 12:54:01.000000', NULL, 1),
(182730, 10195, 3889, '<td valign="top">Great photo.</td>', 'Great photo.', '2003-01-05 12:55:24.000000', NULL, 1),
(182731, 10188, 3883, '<td valign="top">This is a really nice shot.  The slight tilt distracts me and I''d like to be a bit higher from the ground so I could follow that nice curved track out of sight.</td>', 'This is a really nice shot.  The slight tilt distracts me and I''d like to be a bit higher from the ground so I could follow that nice curved track out of sight.', '2003-01-05 12:55:47.000000', NULL, 1),
(182733, 10175, 1031, '<td valign="top">I like the way the to small foreground rocks mirror the composition of the boulders and peaks behind them, but I think it would be stronger and tie together better if cropped above the small rocks, reinforcing the strength of the boulders, and creating a more panoramic look as well.</td>', 'I like the way the to small foreground rocks mirror the composition of the boulders and peaks behind them, but I think it would be stronger and tie together better if cropped above the small rocks, reinforcing the strength of the boulders, and creating a more panoramic look as well.', '2003-01-05 13:00:17.000000', NULL, 1),
(182737, 10147, 1031, '<td valign="top">It''s usually hard to get such good contrast! Nice job -- I look forward to seeing what settings you used...</td>', 'It''s usually hard to get such good contrast! Nice job -- I look forward to seeing what settings you used...', '2003-01-05 13:02:57.000000', NULL, 1),
(182739, 10265, 1031, '<td valign="top">I wish I could say I''ve never seen this sight before, but it looks eeerily like my bike...</td>', 'I wish I could say I''ve never seen this sight before, but it looks eeerily like my bike...', '2003-01-05 13:07:17.000000', NULL, 1),
(182740, 10102, 1031, '<td valign="top">But maybe a good (if bumpy) view?</td>', 'But maybe a good (if bumpy) view?', '2003-01-05 13:10:03.000000', NULL, 1),
(182742, 10234, 6001, '<td valign="top">this photo is awesome. straight awesome.<br/>represents that point of travel where you''re<br/>glad to have gone, but you''re ready to go home.</td>', 'this photo is awesome. straight awesome.represents that point of travel where you''reglad to have gone, but you''re ready to go home.', '2003-01-05 13:13:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(182743, 10320, 1031, '<td valign="top">Yeah, but you need to move it up a touch to make the handrail fall exactly on the 1/3-line...seriously funny, and might have been even more effective if the rectangular displays in the background weren''t there</td>', 'Yeah, but you need to move it up a touch to make the handrail fall exactly on the 1/3-line...seriously funny, and might have been even more effective if the rectangular displays in the background weren''t there', '2003-01-05 13:14:23.000000', NULL, 1),
(182749, 10332, 1031, '<td valign="top">At least it''s not completely covered with advertising...</td>', 'At least it''s not completely covered with advertising...', '2003-01-05 13:26:17.000000', NULL, 1),
(182751, 10160, 4813, '<td valign="top">the border takes away from the photo for me</td>', 'the border takes away from the photo for me', '2003-01-05 13:35:30.000000', NULL, 1),
(182752, 10250, 4813, '<td valign="top">I don''t see the travel reference...can you explain?<br/></td>', 'I don''t see the travel reference...can you explain?', '2003-01-05 13:36:28.000000', NULL, 1),
(182757, 10236, 4813, '<td valign="top">the only reference to travel that I see in this photo is in the title...could you explain?</td>', 'the only reference to travel that I see in this photo is in the title...could you explain?', '2003-01-05 13:51:54.000000', NULL, 1),
(182782, 10330, 811, '<td valign="top">Wonderful shot!  Grabbed my attention and kept it the first time I saw it!</td>', 'Wonderful shot!  Grabbed my attention and kept it the first time I saw it!', '2003-01-05 16:19:58.000000', NULL, 1),
(182784, 10160, 811, '<td valign="top">I really like this shot; framing, composition, etc.  The border, though it didn''t effect your score, seems a little wide.  It almost "swallows" the whole picture and it is difficult to discern how awesome it truly is.</td>', 'I really like this shot; framing, composition, etc.  The border, though it didn''t effect your score, seems a little wide.  It almost "swallows" the whole picture and it is difficult to discern how awesome it truly is.', '2003-01-05 16:21:29.000000', NULL, 1),
(182786, 10140, 3419, '<td valign="top">Very pretty scene - nice colors and composition.</td>', 'Very pretty scene - nice colors and composition.', '2003-01-05 16:26:00.000000', NULL, 1),
(182787, 10289, 3419, '<td valign="top">Too bad you couldn''t get the bird in a little closer. He gets lost among the clouds. Makes a nice abstract photo.</td>', 'Too bad you couldn''t get the bird in a little closer. He gets lost among the clouds. Makes a nice abstract photo.', '2003-01-05 16:27:10.000000', NULL, 1),
(182788, 10266, 3419, '<td valign="top">Good capture of a snowy day - focus is very crisp. Your capture of the exhaust from the vehicle contributes to the "snowy weather" mood.</td>', 'Good capture of a snowy day - focus is very crisp. Your capture of the exhaust from the vehicle contributes to the "snowy weather" mood.', '2003-01-05 16:28:56.000000', NULL, 1),
(182789, 10228, 3419, '<td valign="top">Nice composition and colors. While the lighting is nice, I would prefer it to be more soft or subdued (not so obvious - does that make sense?)</td>', 'Nice composition and colors. While the lighting is nice, I would prefer it to be more soft or subdued (not so obvious - does that make sense?)', '2003-01-05 16:31:26.000000', NULL, 1),
(182790, 10131, 3419, '<td valign="top">Looks like you''re moving out (could be another interpretation for this photo). Composition is good, but the small format makes this photo hard to accurately judge technically.</td>', 'Looks like you''re moving out (could be another interpretation for this photo). Composition is good, but the small format makes this photo hard to accurately judge technically.', '2003-01-05 16:33:10.000000', NULL, 1),
(182791, 10271, 3419, '<td valign="top">A good candidate for the motion challenge! Nice capture.</td>', 'A good candidate for the motion challenge! Nice capture.', '2003-01-05 16:34:22.000000', NULL, 1),
(182793, 10291, 3419, '<td valign="top">The top half of the photo looks just a little bit over-exposed to me - the white of the big boat and the boats in the backgroud is very bright. I''d prefer not to see the shoreline at the front as I feel it detracts from the photo. Good colors, focus, and composition otherwise.</td>', 'The top half of the photo looks just a little bit over-exposed to me - the white of the big boat and the boats in the backgroud is very bright. I''d prefer not to see the shoreline at the front as I feel it detracts from the photo. Good colors, focus, and composition otherwise.', '2003-01-05 16:37:14.000000', NULL, 1),
(182794, 10261, 3419, '<td valign="top">Nice composition and excellent focus on the back of the train. Would prefer crisper focus on the platform, signage, and windows (wall?).</td>', 'Nice composition and excellent focus on the back of the train. Would prefer crisper focus on the platform, signage, and windows (wall?).', '2003-01-05 16:38:45.000000', NULL, 1),
(182795, 10163, 3419, '<td valign="top">Nice concept, but too blurry.</td>', 'Nice concept, but too blurry.', '2003-01-05 16:39:55.000000', NULL, 1),
(182797, 10258, 3419, '<td valign="top">The angle looks really odd - both buildings appear to be leaning in towards each other - more prominently on the left. Did you take this with the camera pointed upwards? While the capture of detail on the buildings is good, the sky and snow are over-exposed, and the trees are soft looking.</td>', 'The angle looks really odd - both buildings appear to be leaning in towards each other - more prominently on the left. Did you take this with the camera pointed upwards? While the capture of detail on the buildings is good, the sky and snow are over-exposed, and the trees are soft looking.', '2003-01-05 16:43:21.000000', NULL, 1),
(182798, 10100, 3419, '<td valign="top">Pretty bathing suite (??). Good composition, and excellent crisp focus and lighting. I like how the sand beneath (or carpet that looks like sand) contributes to the message. Hope you had a good time?</td>', 'Pretty bathing suite (??). Good composition, and excellent crisp focus and lighting. I like how the sand beneath (or carpet that looks like sand) contributes to the message. Hope you had a good time?', '2003-01-05 16:45:08.000000', NULL, 1),
(182801, 10237, 3419, '<td valign="top">I find this photo offensive because you are insulting yourself. You do yourself no favors by doing so in a public forum. In terms of technical merit, your composition is different - my eyes keep moving to the torn corner of the paper. Your exposure settings need some work - the paper should be white, not grey. You might want to try experimenting with white balance?</td>', 'I find this photo offensive because you are insulting yourself. You do yourself no favors by doing so in a public forum. In terms of technical merit, your composition is different - my eyes keep moving to the torn corner of the paper. Your exposure settings need some work - the paper should be white, not grey. You might want to try experimenting with white balance?', '2003-01-05 16:53:47.000000', NULL, 1),
(182802, 10188, 332, '<td valign="top">Good composition.</td>', 'Good composition.', '2003-01-05 16:54:01.000000', NULL, 1),
(182803, 10178, 3419, '<td valign="top">This would be a great photo if all of the key was in focus; composition is great. The background is also just a little too bright for my taste.</td>', 'This would be a great photo if all of the key was in focus; composition is great. The background is also just a little too bright for my taste.', '2003-01-05 16:55:04.000000', NULL, 1),
(182804, 10105, 3419, '<td valign="top">Nice capture of the fireworks, but the small format of the phot makes it difficult to accurately judge technically.</td>', 'Nice capture of the fireworks, but the small format of the phot makes it difficult to accurately judge technically.', '2003-01-05 16:55:51.000000', NULL, 1),
(182805, 10260, 332, '<td valign="top">My favorite this week. Good job. Great composition and good contrast.</td>', 'My favorite this week. Good job. Great composition and good contrast.', '2003-01-05 16:57:24.000000', NULL, 1),
(182806, 10135, 3419, '<td valign="top">Nice snapshot (looks like fun), but the exposure setting that results in dingy looking snow detracts.</td>', 'Nice snapshot (looks like fun), but the exposure setting that results in dingy looking snow detracts.', '2003-01-05 16:57:34.000000', NULL, 1),
(182807, 10171, 332, '<td valign="top">One of my favorite this week. Love the colors and composition. Good job!</td>', 'One of my favorite this week. Love the colors and composition. Good job!', '2003-01-05 16:58:32.000000', NULL, 1),
(182808, 10089, 3419, '<td valign="top">Very good composition. Looks like a magazine ad for the vehicle.</td>', 'Very good composition. Looks like a magazine ad for the vehicle.', '2003-01-05 16:59:37.000000', NULL, 1),
(182809, 10147, 3419, '<td valign="top">Very pretty, and nicely captured.</td>', 'Very pretty, and nicely captured.', '2003-01-05 17:00:36.000000', NULL, 1),
(182810, 10325, 3419, '<td valign="top">Blurry and a little over-exposed on the white shirt.</td>', 'Blurry and a little over-exposed on the white shirt.', '2003-01-05 17:01:23.000000', NULL, 1),
(182811, 10197, 3419, '<td valign="top">The pattern of the brick wall is what makes this shot for me.</td>', 'The pattern of the brick wall is what makes this shot for me.', '2003-01-05 17:02:13.000000', NULL, 1),
(182812, 10175, 3419, '<td valign="top">Beautiful shot - Ansel Adams style. Black and white works well here.</td>', 'Beautiful shot - Ansel Adams style. Black and white works well here.', '2003-01-05 17:03:05.000000', NULL, 1),
(182815, 10202, 4380, '<td valign="top">almost forgot to rate this very excellent entry...nice image and very good composition. congrats.. it''s a perfect 10!!!<br/></td>', 'almost forgot to rate this very excellent entry...nice image and very good composition. congrats.. it''s a perfect 10!!!', '2003-01-05 17:04:36.000000', NULL, 1),
(182816, 10257, 3419, '<td valign="top">Very sharp - but way too bright. Intentional - artistically? The whiteness on the boats makes them all merge into each other. Great composition though!</td>', 'Very sharp - but way too bright. Intentional - artistically? The whiteness on the boats makes them all merge into each other. Great composition though!', '2003-01-05 17:04:40.000000', NULL, 1),
(182818, 10202, 3419, '<td valign="top">Wonderful composition and colors.</td>', 'Wonderful composition and colors.', '2003-01-05 17:05:43.000000', NULL, 1),
(182819, 10094, 3419, '<td valign="top">Beautiful capture and colors.</td>', 'Beautiful capture and colors.', '2003-01-05 17:06:29.000000', NULL, 1),
(182820, 10122, 3419, '<td valign="top">Wonderful capture of the moon - I''m jealous!!</td>', 'Wonderful capture of the moon - I''m jealous!!', '2003-01-05 17:07:03.000000', NULL, 1),
(182821, 10299, 3419, '<td valign="top">Nice composition, but very blue looking - overall. Intentional? Over-exposure and soft focus makes the names on buildings difficult to read, which I find distracting - a little.</td>', 'Nice composition, but very blue looking - overall. Intentional? Over-exposure and soft focus makes the names on buildings difficult to read, which I find distracting - a little.', '2003-01-05 17:08:53.000000', NULL, 1),
(182822, 10113, 3419, '<td valign="top">Small format makes it hard to judge this photo technically. However, composition and capture of lighting are good.</td>', 'Small format makes it hard to judge this photo technically. However, composition and capture of lighting are good.', '2003-01-05 17:10:34.000000', NULL, 1),
(182823, 10248, 2716, '<td valign="top">Nice depth of field.  I like it.  Jacko.</td>', 'Nice depth of field.  I like it.  Jacko.', '2003-01-05 17:10:47.000000', NULL, 1),
(182824, 10236, 3419, '<td valign="top">Lighting, composition, and back-lighting make this an interesting photo. What are these?</td>', 'Lighting, composition, and back-lighting make this an interesting photo. What are these?', '2003-01-05 17:12:19.000000', NULL, 1),
(182826, 10151, 3419, '<td valign="top">Interesting capture of light and shadow. The pole on the left makes me want to move away - it''s in my way.</td>', 'Interesting capture of light and shadow. The pole on the left makes me want to move away - it''s in my way.', '2003-01-05 17:14:43.000000', NULL, 1),
(182828, 10086, 3419, '<td valign="top">Good composition, but focus is a little soft, and photo seems over-exposed due to the bright sunlight from the left.</td>', 'Good composition, but focus is a little soft, and photo seems over-exposed due to the bright sunlight from the left.', '2003-01-05 17:15:55.000000', NULL, 1),
(182830, 10217, 3419, '<td valign="top">This donkey looks tired! Bright light conveys the feeling of a very hot day. Nice composition and capture of detail.</td>', 'This donkey looks tired! Bright light conveys the feeling of a very hot day. Nice composition and capture of detail.', '2003-01-05 17:17:16.000000', NULL, 1),
(182833, 10177, 3419, '<td valign="top">Composition is very nice (the city scape in the background makes it for me), and so are the colors. But the bottom half of the photo looks very noisy and the ships lines are jaggy. Is the noise intentional - artistically?</td>', 'Composition is very nice (the city scape in the background makes it for me), and so are the colors. But the bottom half of the photo looks very noisy and the ships lines are jaggy. Is the noise intentional - artistically?', '2003-01-05 17:21:15.000000', NULL, 1),
(182835, 10160, 3419, '<td valign="top">Pretty scene. The thick black border makes me feel like I''m looking through a window though, rather than feeling like I''m part of the scene.</td>', 'Pretty scene. The thick black border makes me feel like I''m looking through a window though, rather than feeling like I''m part of the scene.', '2003-01-05 17:22:35.000000', NULL, 1),
(182836, 10170, 4813, '<td valign="top">good picture...I would have liked it better if you cropped more</td>', 'good picture...I would have liked it better if you cropped more', '2003-01-05 17:27:39.000000', NULL, 1),
(182837, 10308, 4813, '<td valign="top">cute picture but a little too much junk in the background...5</td>', 'cute picture but a little too much junk in the background...5', '2003-01-05 17:28:42.000000', NULL, 1),
(182838, 10200, 4813, '<td valign="top">I just don''t get it</td>', 'I just don''t get it', '2003-01-05 17:30:00.000000', NULL, 1),
(182842, 10167, 4813, '<td valign="top">the print is horrible, I don''t know what you used for an effect...this would have been better suited for the occupation challenge.</td>', 'the print is horrible, I don''t know what you used for an effect...this would have been better suited for the occupation challenge.', '2003-01-05 17:35:07.000000', NULL, 1),
(182845, 10237, 4813, '<td valign="top">This is a photo contest as much as creativity...I think this picture got too much unnecessary bad press in the forum.  Photo wise I give it a 3 you could have cropped better and used a clean, full sheet of paper.  on Creativity I really liked the idea and would give it an 8.  However as stated in the forum normally works of art including you own is not normally acceptable and I consider this a work of art...However there is no clause as mentioned in the forum so no deduction.  The subtotal for the picture is a 5.5 rounded up to a 6.  However I am not finished yet.  Because the picture was discussed in a forum during voting I feel that is negatively swayed the vote for others so I am giving it a 4 point bonus.  Total 10</td>', 'This is a photo contest as much as creativity...I think this picture got too much unnecessary bad press in the forum.  Photo wise I give it a 3 you could have cropped better and used a clean, full sheet of paper.  on Creativity I really liked the idea and would give it an 8.  However as stated in the forum normally works of art including you own is not normally acceptable and I consider this a work of art...However there is no clause as mentioned in the forum so no deduction.  The subtotal for the picture is a 5.5 rounded up to a 6.  However I am not finished yet.  Because the picture was discussed in a forum during voting I feel that is negatively swayed the vote for others so I am giving it a 4 point bonus.  Total 10', '2003-01-05 17:43:43.000000', NULL, 1),
(182847, 10134, 2011, '<td valign="top">Beautiful</td>', 'Beautiful', '2003-01-05 17:53:30.000000', NULL, 1),
(182849, 10317, 2011, '<td valign="top">This is great. I love the colors and the wear and tear.</td>', 'This is great. I love the colors and the wear and tear.', '2003-01-05 17:55:34.000000', NULL, 1),
(182851, 10163, 2011, '<td valign="top">Of all the plane pics this week, this one is the best.  Love the color and that you left the prop of the plane in the shot.</td>', 'Of all the plane pics this week, this one is the best.  Love the color and that you left the prop of the plane in the shot.', '2003-01-05 17:57:21.000000', NULL, 1),
(182854, 10128, 4517, '<td valign="top">His light. How do you know its not a woman?</td>', 'His light. How do you know its not a woman?', '2003-01-05 18:13:36.000000', NULL, 1),
(182858, 10330, 4648, '<td valign="top">I love this type of photo.  But in this one the sun is just too bright to suit me.  It makes me squint and look away from what actually is a good photo.  I find myself wanting to look at the ice, fishing poles, etc. but can''t.  Because of that I can''t really give it more than a 5.  PTL</td>', 'I love this type of photo.  But in this one the sun is just too bright to suit me.  It makes me squint and look away from what actually is a good photo.  I find myself wanting to look at the ice, fishing poles, etc. but can''t.  Because of that I can''t really give it more than a 5.  PTL', '2003-01-05 18:23:59.000000', NULL, 1),
(182859, 10134, 4648, '<td valign="top">Love this photo, especially the depth of the road in front.  You feel like you can see on and on for miles.  Love how the trees hang over the road and line the road &amp; photo.  Great cropping job.  Was this taken in B&amp;W or changed to B&amp;W.  It''s a great one.  Appears to be natural colors.  Ths is a 10 all the way.  PTL</td>', 'Love this photo, especially the depth of the road in front.  You feel like you can see on and on for miles.  Love how the trees hang over the road and line the road & photo.  Great cropping job.  Was this taken in B&W or changed to B&W.  It''s a great one.  Appears to be natural colors.  Ths is a 10 all the way.  PTL', '2003-01-05 18:26:58.000000', NULL, 1),
(182861, 10180, 4648, '<td valign="top">This is a very relaxing shot, and beautiful.  I expecially like the colors of the kayak against the rest of the shot.  Beautiful sky and landscape.  Overall really good photo.   Would liked to have been able to see his face a little more.  But it''s still good.  8 PTL</td>', 'This is a very relaxing shot, and beautiful.  I expecially like the colors of the kayak against the rest of the shot.  Beautiful sky and landscape.  Overall really good photo.   Would liked to have been able to see his face a little more.  But it''s still good.  8 PTL', '2003-01-05 18:29:30.000000', NULL, 1),
(182863, 10283, 4648, '<td valign="top">Very nice simple photo.  Not cluttered up with a lot of unnecessary things.  Clear good focus and nice cropping.  Very true to live colors.  Nice job.  8 PTL</td>', 'Very nice simple photo.  Not cluttered up with a lot of unnecessary things.  Clear good focus and nice cropping.  Very true to live colors.  Nice job.  8 PTL', '2003-01-05 18:31:25.000000', NULL, 1),
(182864, 10158, 4648, '<td valign="top">It''s really hard to comment on a good photo.  How many ways can you say "I like it.",  "It''s a good photo",  If they''re good it''s obvious the cropping is good, the focus is good, the subject and composition is good, the lighting is good, etc.  Just say  "This is a good photo technically and otherwise and I like it.  And here''s a 9. " PTL</td>', 'It''s really hard to comment on a good photo.  How many ways can you say "I like it.",  "It''s a good photo",  If they''re good it''s obvious the cropping is good, the focus is good, the subject and composition is good, the lighting is good, etc.  Just say  "This is a good photo technically and otherwise and I like it.  And here''s a 9. " PTL', '2003-01-05 18:35:13.000000', NULL, 1),
(182867, 10160, 4648, '<td valign="top">The ONLY fault I find with this photo is the framing if a little off.  I would rather you have taken it from right down the middle of the road so the trees on each side framed the photo naturally.  I especially like the pristineness of the snow in the road - not a track in it.  Also especially good is how the snow is on one side of the trees and not on the other.  This also would have shown better had you had the photo lined up more in the center.  But it is still a beautiful winter shot.  9 PTL</td>', 'The ONLY fault I find with this photo is the framing if a little off.  I would rather you have taken it from right down the middle of the road so the trees on each side framed the photo naturally.  I especially like the pristineness of the snow in the road - not a track in it.  Also especially good is how the snow is on one side of the trees and not on the other.  This also would have shown better had you had the photo lined up more in the center.  But it is still a beautiful winter shot.  9 PTL', '2003-01-05 18:39:14.000000', NULL, 1),
(182869, 10170, 4648, '<td valign="top">A unique take on the challenge.  A nice change also.  And it is a beautiful butterfly.  This sounds strange coming from me but more of the grass should have been out of focus, so the butterfly would have stood out more.  But it is still a beautiful shot.  I especially like the contrast of the green grass and dead brown grass.  Great job.  8 PTL</td>', 'A unique take on the challenge.  A nice change also.  And it is a beautiful butterfly.  This sounds strange coming from me but more of the grass should have been out of focus, so the butterfly would have stood out more.  But it is still a beautiful shot.  I especially like the contrast of the green grass and dead brown grass.  Great job.  8 PTL', '2003-01-05 18:41:52.000000', NULL, 1),
(182871, 10165, 4648, '<td valign="top">Need something in focust to look at.  Sorry but this is a 1 in my book.  PTL</td>', 'Need something in focust to look at.  Sorry but this is a 1 in my book.  PTL', '2003-01-05 18:43:20.000000', NULL, 1),
(182872, 10202, 4055, '<td valign="top">Nice shot. Lovely colours. Like the border too. Would have liked to see a little more of the hills in the background but it´s not a big deal. High score.</td>', 'Nice shot. Lovely colours. Like the border too. Would have liked to see a little more of the hills in the background but it´s not a big deal. High score.', '2003-01-05 18:45:16.000000', NULL, 1),
(182873, 10188, 4055, '<td valign="top">This is the kind of photos I really like. B&amp;w (sepia) and great composition. Perhaps just a little more of the hills in the background. But it depends on what there is to see. I had probably also made it a little bit darker, but that´s just a matter of taste. High score from me. Well done.</td>', 'This is the kind of photos I really like. B&w (sepia) and great composition. Perhaps just a little more of the hills in the background. But it depends on what there is to see. I had probably also made it a little bit darker, but that´s just a matter of taste. High score from me. Well done.', '2003-01-05 18:50:31.000000', NULL, 1),
(182874, 10284, 4648, '<td valign="top">The hand is out of focus and doesn''t look like it is really going to pick up anything or putting anything in, just kinds placed in the photo, from the angle of it.  Maybe if the passport were actually in the hand.  I like the simpleness and how uncluttered the shot is.  It is very well focused otherwise and I basically like it.  Personally I wouldn''t have cropped off the corner of the wallet.  The shadow is harsh.  Maybe use a light on that side aimed at the hand and parallel with the arm.  Otherwise a good photo.  7 PTL</td>', 'The hand is out of focus and doesn''t look like it is really going to pick up anything or putting anything in, just kinds placed in the photo, from the angle of it.  Maybe if the passport were actually in the hand.  I like the simpleness and how uncluttered the shot is.  It is very well focused otherwise and I basically like it.  Personally I wouldn''t have cropped off the corner of the wallet.  The shadow is harsh.  Maybe use a light on that side aimed at the hand and parallel with the arm.  Otherwise a good photo.  7 PTL', '2003-01-05 18:50:33.000000', NULL, 1),
(182877, 10266, 4055, '<td valign="top">This could be outside my door here in Sweden right now. A lovely shot. Great composition and interesting. Cold and lovely. High score from Sweden.</td>', 'This could be outside my door here in Sweden right now. A lovely shot. Great composition and interesting. Cold and lovely. High score from Sweden.', '2003-01-05 18:54:51.000000', NULL, 1),
(182879, 10095, 4648, '<td valign="top">Could just be me or the design of the pyramid but it looks out of focus, everything except the trees.  This is how it appears to me.  PTL 3</td>', 'Could just be me or the design of the pyramid but it looks out of focus, everything except the trees.  This is how it appears to me.  PTL 3', '2003-01-05 18:57:07.000000', NULL, 1),
(182883, 10253, 4648, '<td valign="top">This is an especially nice photo, not an attention grabbing, "wow" of a 10, but exceptionally good.  I especially like the contrast of the clean, clear colors of the close by shrubbery and trees, versus the haze hanging over the surround, further away, greenery. Everything technical is very good.  Worthy of an 8.  PTL</td>', 'This is an especially nice photo, not an attention grabbing, "wow" of a 10, but exceptionally good.  I especially like the contrast of the clean, clear colors of the close by shrubbery and trees, versus the haze hanging over the surround, further away, greenery. Everything technical is very good.  Worthy of an 8.  PTL', '2003-01-05 19:08:29.000000', NULL, 1),
(182885, 10230, 3599, '<td valign="top">Wonderull picture of this landmark.  I would have tried to keep the five street lights in the lower left out of the shot.  Other than that great shot.</td>', 'Wonderull picture of this landmark.  I would have tried to keep the five street lights in the lower left out of the shot.  Other than that great shot.', '2003-01-05 19:11:47.000000', NULL, 1),
(182886, 10201, 4648, '<td valign="top">Where''s the boat?  The sky appears dreary.  I love the mist coming from the falls and the cloudiness of the water rushing over the falls.  This shows such power and speed to the water.  Obviously your are not taking this from the "picture shooting" area.  I like that you included the "Non-falls" area on the left and the bank of the bottome right corner.  To me it just adds something extra.  All most people show is the middle of the falls itself.  I really like this angled shot.  Shame it wastn''t a bright sunny day.  9 PTL</td>', 'Where''s the boat?  The sky appears dreary.  I love the mist coming from the falls and the cloudiness of the water rushing over the falls.  This shows such power and speed to the water.  Obviously your are not taking this from the "picture shooting" area.  I like that you included the "Non-falls" area on the left and the bank of the bottome right corner.  To me it just adds something extra.  All most people show is the middle of the falls itself.  I really like this angled shot.  Shame it wastn''t a bright sunny day.  9 PTL', '2003-01-05 19:13:40.000000', NULL, 1),
(182887, 10332, 4648, '<td valign="top">Does this ever take me back years.  The old country school bus stops.  Hate to admit how many years ago that was.  Looks almost like Ohio or WVa.  And it''s a beautiful photo with great depth.  I''d love to be standing on top of that knoll.  This is a 9.  PTL</td>', 'Does this ever take me back years.  The old country school bus stops.  Hate to admit how many years ago that was.  Looks almost like Ohio or WVa.  And it''s a beautiful photo with great depth.  I''d love to be standing on top of that knoll.  This is a 9.  PTL', '2003-01-05 19:16:51.000000', NULL, 1),
(182888, 10298, 2716, '<td valign="top">Great shot.  I wish I was there.  Nice colours and cool motion on the ball.  Good job and good luck.  Jacko  9</td>', 'Great shot.  I wish I was there.  Nice colours and cool motion on the ball.  Good job and good luck.  Jacko  9', '2003-01-05 19:17:50.000000', NULL, 1),
(182889, 10201, 2716, '<td valign="top">Ah man, I went there when I was 7 and have always wanted to go back.  Lucky you.  Good shot.</td>', 'Ah man, I went there when I was 7 and have always wanted to go back.  Lucky you.  Good shot.', '2003-01-05 19:18:24.000000', NULL, 1),
(182890, 10105, 2716, '<td valign="top">Excellent shot.  It''s too  bad the picture is so small.  I''d love to see more detail.  Excellent capture.   Jacko. 8</td>', 'Excellent shot.  It''s too  bad the picture is so small.  I''d love to see more detail.  Excellent capture.   Jacko. 8', '2003-01-05 19:19:12.000000', NULL, 1),
(182891, 10325, 3599, '<td valign="top">You need to learn how to pack:)</td>', 'You need to learn how to pack:)', '2003-01-05 19:19:17.000000', NULL, 1),
(182892, 10217, 4648, '<td valign="top">At first glance one would say this photo is too light or washed out.  But when you see the donkey and the fodder you know it isn''t.  Looks like the cushion you sit on is sliding off the donkey''s back.  You did a wonderful job of catching him in mid-step and getting everything in focus.  Great photo.  9 PTL</td>', 'At first glance one would say this photo is too light or washed out.  But when you see the donkey and the fodder you know it isn''t.  Looks like the cushion you sit on is sliding off the donkey''s back.  You did a wonderful job of catching him in mid-step and getting everything in focus.  Great photo.  9 PTL', '2003-01-05 19:19:48.000000', NULL, 1),
(182893, 10157, 2716, '<td valign="top">Been there, done that.  Good job at capturing the mood of what you''re trying to portray (make any sense?).  Good job.</td>', 'Been there, done that.  Good job at capturing the mood of what you''re trying to portray (make any sense?).  Good job.', '2003-01-05 19:20:12.000000', NULL, 1),
(182895, 10240, 2716, '<td valign="top">That is hillarious!  I''m trying to see the relevance to travel.  I''ll revisit this shot later.  Jacko.</td>', 'That is hillarious!  I''m trying to see the relevance to travel.  I''ll revisit this shot later.  Jacko.', '2003-01-05 19:21:18.000000', NULL, 1),
(182897, 10195, 2716, '<td valign="top">Very nice colours.  Good job.  Jacko.  9</td>', 'Very nice colours.  Good job.  Jacko.  9', '2003-01-05 19:23:49.000000', NULL, 1),
(182899, 10188, 2716, '<td valign="top">Good use of the curves.  Jakco.</td>', 'Good use of the curves.  Jakco.', '2003-01-05 19:24:17.000000', NULL, 1),
(182900, 10100, 4648, '<td valign="top">It''s either too cluttered or cropped to tightly. I can''t decide which.  I think cluttered, because it appears you used two copies of the same brochure;  maybe to make it look like more?  One or two brochures is enough.  And the background bothers me.  Again if zoomed back more we could see that it is a bathing suit laying on something else.  These are just personal opinions.  Still I''d give this a 6</td>', 'It''s either too cluttered or cropped to tightly. I can''t decide which.  I think cluttered, because it appears you used two copies of the same brochure;  maybe to make it look like more?  One or two brochures is enough.  And the background bothers me.  Again if zoomed back more we could see that it is a bathing suit laying on something else.  These are just personal opinions.  Still I''d give this a 6', '2003-01-05 19:24:25.000000', NULL, 1),
(182901, 10258, 2716, '<td valign="top">Good job, I''ll have to visit it some day.  Jacko.  8</td>', 'Good job, I''ll have to visit it some day.  Jacko.  8', '2003-01-05 19:25:31.000000', NULL, 1),
(182902, 10260, 3599, '<td valign="top">There is either too much sky or too much grass.  Crop out either one and you get a 10 from me.</td>', 'There is either too much sky or too much grass.  Crop out either one and you get a 10 from me.', '2003-01-05 19:25:39.000000', NULL, 1),
(182903, 10157, 4648, '<td valign="top">I realize this is intentionally out of focus to show movement (frantic packing), but it''s too much so for me personally.  All I can give it is a 3.  The suitcase is in focus.  PTL</td>', 'I realize this is intentionally out of focus to show movement (frantic packing), but it''s too much so for me personally.  All I can give it is a 3.  The suitcase is in focus.  PTL', '2003-01-05 19:26:36.000000', NULL, 1),
(182904, 10295, 4648, '<td valign="top">I can''t tell if this shot is really misty or blow out and overly lightened to appear misty.  Personally I can''t give it more than a 4.  PTL</td>', 'I can''t tell if this shot is really misty or blow out and overly lightened to appear misty.  Personally I can''t give it more than a 4.  PTL', '2003-01-05 19:28:22.000000', NULL, 1),
(182905, 10328, 4648, '<td valign="top">To me this appears to be a fountain of wild mustangs, and I don''t know what it has to do with travel in the way the challenge meant it.  I''ll give a 5 for the clarity of the photo though.  PTL</td>', 'To me this appears to be a fountain of wild mustangs, and I don''t know what it has to do with travel in the way the challenge meant it.  I''ll give a 5 for the clarity of the photo though.  PTL', '2003-01-05 19:31:47.000000', NULL, 1),
(182908, 10246, 4648, '<td valign="top">Wonderful photo.  He seems to be really enjoying the scenery flying by.  He won''t remember this but the photo will prove he took a train ride.  Love how you let the train window frame the photo.  You couldn''t do much about the angle of the window.....Yes you could have.  It would have been better had you gotten down and taken the photo up at an angle with the window so it would frame the photo perfectly.  Hind site.  Still a good shot and worth an 8.  PTL</td>', 'Wonderful photo.  He seems to be really enjoying the scenery flying by.  He won''t remember this but the photo will prove he took a train ride.  Love how you let the train window frame the photo.  You couldn''t do much about the angle of the window.....Yes you could have.  It would have been better had you gotten down and taken the photo up at an angle with the window so it would frame the photo perfectly.  Hind site.  Still a good shot and worth an 8.  PTL', '2003-01-05 19:36:42.000000', NULL, 1),
(182911, 10325, 4648, '<td valign="top">Poor lighting.  The light in the next room distracts in that corner.  The white shirt is blown out looks like by the flash.  The top of the photo is too dark, and off colored by the lighting.  And you have too many shadows.  You couldn''t very well crop out the light in that room, so should have turned it off.  Need more natural light, or extra lights to light the scene evenly.  4  PTL.</td>', 'Poor lighting.  The light in the next room distracts in that corner.  The white shirt is blown out looks like by the flash.  The top of the photo is too dark, and off colored by the lighting.  And you have too many shadows.  You couldn''t very well crop out the light in that room, so should have turned it off.  Need more natural light, or extra lights to light the scene evenly.  4  PTL.', '2003-01-05 19:40:55.000000', NULL, 1),
(182913, 10110, 5391, '<td valign="top">Excellent composition.  Very nice shot!</td>', 'Excellent composition.  Very nice shot!', '2003-01-05 19:48:42.000000', NULL, 1),
(182914, 10311, 4648, '<td valign="top">Personally I don''t care for the color of this at all.  It is also way too dark to see anything but not dark enough to be a night shot for me.  Sorry, but personally all I can give this is a 3.  I gave it a three because it appears to be in good focus and has nice cropping and composition.  Otherwise it would have been lower.  PTL</td>', 'Personally I don''t care for the color of this at all.  It is also way too dark to see anything but not dark enough to be a night shot for me.  Sorry, but personally all I can give this is a 3.  I gave it a three because it appears to be in good focus and has nice cropping and composition.  Otherwise it would have been lower.  PTL', '2003-01-05 19:48:55.000000', NULL, 1),
(182916, 10194, 4648, '<td valign="top">Good idea, and probably close to real life.  For me it''s too cluttered.  In my opinion by the time you are down to the budget part you at least have picked a theme, ie snow, beach, mountains, etc. and are comparing those prices.  This would eliminate the clutter by cutting down on the number of brochures.  Making sense?  Also the hand appears to be out of focus.  But it is still a decent shot worth a 6.  PTL</td>', 'Good idea, and probably close to real life.  For me it''s too cluttered.  In my opinion by the time you are down to the budget part you at least have picked a theme, ie snow, beach, mountains, etc. and are comparing those prices.  This would eliminate the clutter by cutting down on the number of brochures.  Making sense?  Also the hand appears to be out of focus.  But it is still a decent shot worth a 6.  PTL', '2003-01-05 19:56:44.000000', NULL, 1),
(182917, 10277, 4648, '<td valign="top">Probably most honest photo and title of all.  And I would have too if I''d had snow to play in.  Good clear focus, I can even read the license plate.  Good cropping.  Nice compositin and good execution.  Good shot.  8  PLT</td>', 'Probably most honest photo and title of all.  And I would have too if I''d had snow to play in.  Good clear focus, I can even read the license plate.  Good cropping.  Nice compositin and good execution.  Good shot.  8  PLT', '2003-01-05 20:00:02.000000', NULL, 1),
(182919, 10167, 4648, '<td valign="top">My sons is too.  My thoughts are with you both.  This rather hard to dicipher.  Dark to hide which camoflauge it is?  It appears to be over sharpened.  Because your called to duty I like to give you a 10, BUT I have to score the photo and all I can give it is a 2.  PTL</td>', 'My sons is too.  My thoughts are with you both.  This rather hard to dicipher.  Dark to hide which camoflauge it is?  It appears to be over sharpened.  Because your called to duty I like to give you a 10, BUT I have to score the photo and all I can give it is a 2.  PTL', '2003-01-05 20:04:31.000000', NULL, 1),
(182921, 10135, 4648, '<td valign="top">It''s a shame the photo is so dark we can''t see their faces.  I''d love to see the expressions.  I like to cropping and the focus and the subject and the compotions.  Just need better execution.  5 PTL</td>', 'It''s a shame the photo is so dark we can''t see their faces.  I''d love to see the expressions.  I like to cropping and the focus and the subject and the compotions.  Just need better execution.  5 PTL', '2003-01-05 20:06:49.000000', NULL, 1),
(182922, 10168, 4648, '<td valign="top">Whoa......The towers are about to fall over, and so am I looking at them.  This is otherwise a beautiful photo of a beautiful sunset.  You should have let the mountains be whatever and straightened the towers.  They are actually what first catches you eyes.  Course that could be because they are leaning.  4 PTL</td>', 'Whoa......The towers are about to fall over, and so am I looking at them.  This is otherwise a beautiful photo of a beautiful sunset.  You should have let the mountains be whatever and straightened the towers.  They are actually what first catches you eyes.  Course that could be because they are leaning.  4 PTL', '2003-01-05 20:09:17.000000', NULL, 1),
(182926, 10338, 4648, '<td valign="top">How in the world did you get so close to get this shot?  Must have some telephoto.  Started to say don''t ruin it by B&amp;W but he may have faded into the background if it wasn''t green.  I''d still like to see it in color.  Nature shots are just so beautiful in natural colors.  Good photo thought.  As is it''s a 7.  Color would have been a 9.  But''s that''s justs me.  PTL</td>', 'How in the world did you get so close to get this shot?  Must have some telephoto.  Started to say don''t ruin it by B&W but he may have faded into the background if it wasn''t green.  I''d still like to see it in color.  Nature shots are just so beautiful in natural colors.  Good photo thought.  As is it''s a 7.  Color would have been a 9.  But''s that''s justs me.  PTL', '2003-01-05 20:13:49.000000', NULL, 1),
(182927, 10188, 4411, '<td valign="top">Great shot. The low shooting angle works really well, as does the sepia. One of my favourites this week.</td>', 'Great shot. The low shooting angle works really well, as does the sepia. One of my favourites this week.', '2003-01-05 20:14:57.000000', NULL, 1),
(182928, 10220, 4648, '<td valign="top">Nothing is in focus.  Need some focus somewhere.  1.  PTL</td>', 'Nothing is in focus.  Need some focus somewhere.  1.  PTL', '2003-01-05 20:15:44.000000', NULL, 1),
(182929, 10246, 4411, '<td valign="top">Excellent. Brought a smile to my face. Nice composition, lovely idea. Well done.<br/> <br/>Bumping to a 10, I love this photo!</td>', 'Excellent. Brought a smile to my face. Nice composition, lovely idea. Well done. Bumping to a 10, I love this photo!', '2003-01-05 20:15:56.000000', NULL, 1),
(182930, 10151, 4411, '<td valign="top">Great composition. It''s a shame the row of chairs didn''t end after the first 4, but that takes away very little. I really like the colours in this shot. Well done.</td>', 'Great composition. It''s a shame the row of chairs didn''t end after the first 4, but that takes away very little. I really like the colours in this shot. Well done.', '2003-01-05 20:17:27.000000', NULL, 1),
(182931, 10126, 4648, '<td valign="top">Beautiful appolusa.  Did you travel here to take this beautiful photo, or do they do the traveling.  It''s a beautiful, well executed photo, but I''m not real sure what it has to do with travel.  But because of the quality of the photo, it''s be among my favorites, I''ll have to give you an 8.  PTL</td>', 'Beautiful appolusa.  Did you travel here to take this beautiful photo, or do they do the traveling.  It''s a beautiful, well executed photo, but I''m not real sure what it has to do with travel.  But because of the quality of the photo, it''s be among my favorites, I''ll have to give you an 8.  PTL', '2003-01-05 20:20:33.000000', NULL, 1),
(182932, 10101, 4411, '<td valign="top">A good idea but the noise absolutely murders this one for me.<br/>A bit of playing around in photoshop should get you a decent picture for your album though.</td>', 'A good idea but the noise absolutely murders this one for me.A bit of playing around in photoshop should get you a decent picture for your album though.', '2003-01-05 20:21:36.000000', NULL, 1),
